static void on_end(void *ctx) { (void)ctx; calls++; }
static void on_row(void *ctx, int y, int x0, int x1) {
  (void)ctx;
  calls++;
  memcpy(shadow + (size_t)y * W + x0, cv.px + (size_t)y * W + x0,
         (size_t)(x1 - x0 + 1) * sizeof(uint16_t));
