  TEST_ASSERT_EQUAL_INT(1, count);
  TEST_ASSERT_EQUAL_INT(W - 1, rows[0].x1);
}

void test_many_nearly_full_rows_fall_back_to_a_full_push(void) {
  int count = 0;
