void test_present_calls_nothing_when_nothing_is_dirty(void) {
  nevents = 0;
  TEST_ASSERT_EQUAL_INT(0, push_present(&cv, rows, &sink, false));
  TEST_ASSERT_EQUAL_INT(0, nevents);
