  if (!use_disc) return memcmp(shadow, cv.px, (size_t)W * H * sizeof(uint16_t)) == 0;
  for (int y = 0; y < H; y++) {
    int x0, x1;
    if (!canvas_visible_span(&cv, y, &x0, &x1)) continue;
    if (memcmp(shadow + (size_t)y * W + x0, cv.px + (size_t)y * W + x0,
