399	        void Panel_AMOLED::setWindow(uint_fast16_t xs, uint_fast16_t ys, uint_fast16_t xe, uint_fast16_t ye)
400	        {
401	            if (xs > xe || xe > _width-1) { return; }
402	            if (ys > ye || ye > _height-1) { return; }
403	
404	            // apply offsets
405	            xs += _colstart;
406	            xe += _colstart;
407	            // Set limit
408	            if ((xe - xs) >= _width) { xs = 0; xe = _width - 1; }
409	
410	            // ESP_LOGD("Panel_AMOLED","setWindow %d %d %d %d", xs, ys, xe, ye);
411	            uint16_t w = (xe-xs)+1;
412	            if(xs%2!=0 || w%2!=0) { // Panel_AMOLED restriction: x and w must be divisible by 2
413	                // ESP_LOGD("LGFX", "clip coords aren't aligned");
414	                return;
415	            }
416	
417	
418	            {
419	                // Set Column Start Address (CASET)
420	                write_cmd(0x2A);
421	                _bus->writeCommand(__builtin_bswap32(xs << 16 | xe), 32);
422	            }
423	
424	            ys += _rowstart;
425	            ye += _rowstart;
426	            if ((ye - ys) >= _height) { ys = 0; ye = _height - 1; }
427	            {
428	                // Set Row Start Address (RASET)
429	                write_cmd(0x2B);
430	                _bus->writeCommand(__builtin_bswap32(ys << 16 | ye), 32);
431	            }
432	        }
