  int count = 0;
  add_disc(&cv);
  canvas_fill_rect(&cv, 233, 100, 1, 266, C1);
  TEST_ASSERT_EQUAL_INT(PUSH_ROWS, push_plan(&cv, rows, &count, true));
  TEST_ASSERT_EQUAL_INT(266, count);
  TEST_ASSERT_EQUAL_INT(1, groups_in(rows, count));
}

